-- Server-phase reference migration. Apply only after choosing a managed Postgres/auth provider.
create table profiles(id uuid primary key, display_name text not null check(length(display_name) between 1 and 80), exam text, timezone text not null, study_day_reset smallint not null default 4 check(study_day_reset between 0 and 23), created_at timestamptz not null default now());
create table subjects(id uuid primary key, owner_id uuid not null references profiles(id) on delete cascade, name text not null check(length(name) between 1 and 80), color text not null, target_minutes int not null default 0 check(target_minutes>=0), archived_at timestamptz, created_at timestamptz not null default now(), unique(owner_id,name));
create table tasks(id uuid primary key, owner_id uuid not null references profiles(id) on delete cascade, subject_id uuid references subjects(id) on delete set null, title text not null check(length(title) between 1 and 240), status text not null default 'open' check(status in('open','doing','done','cancelled')), estimate_minutes int check(estimate_minutes between 0 and 10080), due_at timestamptz, created_at timestamptz not null default now());
create table study_sessions(id uuid primary key, owner_id uuid not null references profiles(id) on delete cascade, subject_id uuid references subjects(id) on delete set null, task_id uuid references tasks(id) on delete set null, started_at timestamptz not null, ended_at timestamptz, paused_ms bigint not null default 0 check(paused_ms>=0), duration_ms bigint check(duration_ms>=0), source text not null default 'timer' check(source in('timer','manual','offline_sync')), focus_rating smallint check(focus_rating between 1 and 5), focus_score smallint check(focus_score between 0 and 100), questions_attempted int check(questions_attempted>=0), questions_correct int check(questions_correct>=0), client_request_id uuid not null unique, created_at timestamptz not null default now());
create unique index one_active_timer_per_user on study_sessions(owner_id) where ended_at is null;
create index sessions_owner_started on study_sessions(owner_id,started_at desc);create index tasks_owner_due on tasks(owner_id,due_at) where status='open';
